def f(I):
    I=np.array(I); h,w=I.shape; n=h//2; m=w//2
    Q={k:I[:n,:m] if k=='tl' else I[:n,m:] if k=='tr' else I[n:,:m] if k=='bl' else I[n:,m:],}
    # pick by smallest distance to uniform block of modal color
    def noise(q):
        v,qv=q.flatten(), np.bincount(q.flatten()).argmax()
        return int((v!=qv).sum())
    best=min(Q.items(), key=lambda kv: noise(kv[1]))
    return best[1].tolist()
