from scipy import ndimage
def quads(M):
    h,w=M.shape; return {'tl':M[:h//2,:w//2],'tr':M[:h//2,w//2:],'bl':M[h//2:,:w//2],'br':M[h//2:,w::] if False else M[h//2:,w//2:]}
D=np.array(G['Demo pair 1 input']); T=np.array(G['Test input'])
dQ=quads(D); tQ=quads(T)
for prefix,Q in [('demo',dQ),('test',tQ)]:
    print('---',prefix)
    for name,qv in Q.items():
        c=dict(zip(*np.unique(qv,return_counts=True)))
        maj=max(c,key=c.get)
        # minority connectivity comps
        others={int(k) for k in c if k!=maj}
        for oc in others:
            lab,n=ndimage.label(qv==oc)
            sizes=sorted([int(s) for s in np.bincount(lab.flatten())[1:]],reverse=True)
            print(name,'noise',oc,'ncomp',n,'sizes',sizes)

